interface.definition:
#"SYSTEM_SYSRULES_sectionLayout_v1"(
  label: "Operations Review",
  labelColor: "SECONDARY",
  showWhen: ri!showWhen,
  contents: {
    #"SYSTEM_SYSRULES_richTextDisplayField"(
      labelPosition: "COLLAPSED",
      value: {
        #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: {"To be completed by DPP Operations"},
          size: "SMALL",
          style: "EMPHASIS"
        )
      }
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          showDividers: true,
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_textField"(
                  label: "Is additional follow up required?",
                  labelPosition: "ABOVE",
                  readOnly: true,
                  value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                    value: index(ri!nomination, "isAdditionalFollowUpReq", null),
                    isBoolean: true
                  )
                ),
                /*a!textField(*/
                  /*label: "Does the nomination need to be reapproved by the BU?",*/
                  /*labelPosition: "ABOVE",*/
                  /*readOnly: true,*/
                  /*value:  rule!CAW_displayReadOnlyField(*/
                    /*value: index(ri!nomination, "isReapprovedByBU", null),*/
                    /*isBoolean: true*/
                  /*)*/
                /*),*/
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "",
                  value: {
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text:"BU Reapproval Completed   ",
                      style: "STRONG"
                    ),
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: if(
                        and(
                          ri!nomination.isReapprovedByBUCompleted = true,
                          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBU)
                        ),
                        "check-circle",
                        if(
                          and(
                            ri!nomination.isReapprovedByBU = true,
                            #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBUCompleted)
                          ),
                          /*"hourglass",*/
                          "clock-o",
                          if(
                            and(
                              #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBU),
                              #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBUCompleted)
                            ),
                            "minus-circle",
                            null
                          )
                        )
                      ),
                      linkStyle: "STANDALONE",
                      color: if(
                        and(
                          ri!nomination.isReapprovedByBUCompleted = true,
                          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBU)
                        ),
                        "POSITIVE",
                        if(
                          and(
                            ri!nomination.isReapprovedByBU = true,
                            #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBUCompleted)
                          ),
                          "ACCENT",
                          if(
                            and(
                              #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBU),
                              #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBUCompleted)
                            ),
                            "NEGATIVE",
                            null
                          )
                        )
                      ),
                      size: "MEDIUM",
                      caption: if(
                        and(
                          ri!nomination.isReapprovedByBUCompleted = true,
                          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBU)
                        ),
                        "Completed",
                        if(
                          and(
                            ri!nomination.isReapprovedByBU = true,
                            #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBUCompleted)
                          ),
                          "In Progress",
                          if(
                            and(
                              #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBU),
                              #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isReapprovedByBUCompleted)
                            ),
                            "Not Requested",
                            null
                          )
                        )
                      )
                    )
                  }
                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        label: "",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text:"Inspections Review Completed   ",
                            style: "STRONG"
                          ),
                          #"SYSTEM_SYSRULES_richTextIcon"(
                            icon: if(
                              and(
                                ri!nomination.isInspectionsReviewCompleted = true,
                                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReview)
                              ),
                              "check-circle",
                              if(
                                and(
                                  ri!nomination.isInspectionsReview = true,
                                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReviewCompleted)
                                ),
                                /*"hourglass",*/
                                "clock-o",
                                if(
                                  and(
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReview),
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReviewCompleted)
                                  ),
                                  "minus-circle",
                                  null
                                )
                              )
                            ),
                            linkStyle: "STANDALONE",
                            color: if(
                              and(
                                ri!nomination.isInspectionsReviewCompleted = true,
                                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReview)
                              ),
                              "POSITIVE",
                              if(
                                and(
                                  ri!nomination.isInspectionsReview = true,
                                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReviewCompleted)
                                ),
                                "ACCENT",
                                if(
                                  and(
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReview),
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReviewCompleted)
                                  ),
                                  "NEGATIVE",
                                  null
                                )
                              )
                            ),
                            size: "MEDIUM",
                            caption: if(
                              and(
                                ri!nomination.isInspectionsReviewCompleted = true,
                                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReview)
                              ),
                              "Completed",
                              if(
                                and(
                                  ri!nomination.isInspectionsReview = true,
                                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReviewCompleted)
                                ),
                                "In Progress",
                                if(
                                  and(
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReview),
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isInspectionsReviewCompleted)
                                  ),
                                  "Not Requested",
                                  null
                                )
                              )
                            )
                          )
                        }
                      )
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        label: "",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text:"HR Review Completed   ",
                            style: "STRONG"
                          ),
                          #"SYSTEM_SYSRULES_richTextIcon"(
                            icon: if(
                              and(
                                ri!nomination.isHRReviewCompleted = true,
                                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReview)
                              ),
                              "check-circle",
                              if(
                                and(
                                  ri!nomination.isHRReview = true,
                                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReviewCompleted)
                                ),
                                /*"hourglass",*/
                                "clock-o",
                                if(
                                  and(
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReview),
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReviewCompleted)
                                  ),
                                  "minus-circle",
                                  null
                                )
                              )
                            ),
                            linkStyle: "STANDALONE",
                            color: if(
                              and(
                                ri!nomination.isHRReviewCompleted = true,
                                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReview)
                              ),
                              "POSITIVE",
                              if(
                                and(
                                  ri!nomination.isHRReview = true,
                                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReviewCompleted)
                                ),
                                "ACCENT",
                                if(
                                  and(
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReview),
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReviewCompleted)
                                  ),
                                  "NEGATIVE",
                                  null
                                )
                              )
                            ),
                            size: "MEDIUM",
                            caption: if(
                              and(
                                ri!nomination.isHRReviewCompleted = true,
                                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReview)
                              ),
                              "Completed",
                              if(
                                and(
                                  ri!nomination.isHRReview = true,
                                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReviewCompleted)
                                ),
                                "In Progress",
                                if(
                                  and(
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReview),
                                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isHRReviewCompleted)
                                  ),
                                  "Not Requested",
                                  null
                                )
                              )
                            )
                          )
                        }
                      )
                    )
                  }
                )
              }
            )
          }
        ),
        #"SYSTEM_SYSRULES_paragraphField"(
          label: "Operations Comments",
          labelPosition: "ABOVE",
          readOnly: true,
          value:#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
            value: index(ri!nomination, "operationsComments", null),
            isBoolean: false
          ),
          height: "MEDIUM"
        )
      }
    )
  },
  isCollapsible: true,
  divider: "ABOVE",
  dividerWeight: "THIN",
  marginBelow: "STANDARD"
),
